package qtest

import (
	"bytes"
	"context"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/chucklehead-dev/gotogether/qenv"
	"github.com/chucklehead-dev/gotogether/qobs"
)

// No generated byte sequence is a serialized tape. The header-like prefix
// found by streams' fuzzer must be consumed as choices, not an upgrade error.
func TestFuzzBytesTreatEveryPrefixAsEntropy(t *testing.T) {
	for _, prefix := range [][]byte{
		{255, 'q', 'c', 48},
		{255, 'q', 'c', byte(qenv.BytesVersion)},
		{255, 'q', 'c', 0},
		{255, 'q', 'c'},
	} {
		b := fuzzBytes(prefix, qenv.NoFaults)
		for i, want := range prefix {
			if got := b.Choose("sched.raw", 256); got != int(want) {
				t.Fatalf("prefix %x byte %d: %d, want %d", prefix, i, got, want)
			}
		}
		if b.Err() != nil || b.Choose("sched.end", 256) != 0 {
			t.Fatalf("prefix %x: exhausted chooser error %v", prefix, b.Err())
		}
	}
}

func TestFuzzEncodedSeedsRetainChoicesAndVersionChecks(t *testing.T) {
	rates := qenv.Rates{Default: .5}
	choices := []qenv.Choice{
		{Kind: "sched.narrow", N: 3, Value: 2},
		{Kind: "sched.wide", N: 512, Value: 400},
		{Kind: "fault.binary", N: 2, Value: 1},
		{Kind: "fault.three", N: 3, Value: 2},
		{Kind: "fault.nominal", N: 3, Value: 0},
	}
	encoded, err := qenv.EncodeChoices(choices, rates)
	if err != nil {
		t.Fatal(err)
	}
	before := slices.Clone(encoded)
	payload, err := fuzzSeedPayload(encoded, rates)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(encoded, before) || len(payload) >= len(encoded) {
		t.Fatal("decoding changed the recording or retained its framing")
	}
	generated := fuzzBytes(payload, rates)
	persisted := qenv.FromBytes(encoded, rates)
	for _, c := range choices {
		if got, recorded := generated.Choose(c.Kind, c.N), persisted.Choose(c.Kind, c.N); got != c.Value || recorded != c.Value {
			t.Fatalf("%s: generated %d, recording %d, want %d", c.Kind, got, recorded, c.Value)
		}
	}
	for _, version := range []byte{0, byte(qenv.BytesVersion + 1), 48} {
		bad := slices.Clone(encoded)
		bad[3] = version
		if _, err := fuzzSeedPayload(bad, rates); err == nil || !strings.Contains(err.Error(), "byte rule version") {
			t.Errorf("version %d: %v, want persisted-version diagnostic", version, err)
		}
	}
	for _, raw := range [][]byte{nil, {2}, {255, 'q', 'c'}} {
		if _, err := fuzzSeedPayload(raw, rates); err == nil || !strings.Contains(err.Error(), "qenv.EncodeChoices") {
			t.Errorf("explicit raw seed %x: %v, want encoding guidance", raw, err)
		}
	}
}

// Exercise the real System.Fuzz callback, not just its decoder helper.
// f.Add supplies generated-corpus entropy; the optional seed is a recording.
func FuzzSystemRawEntropy(f *testing.F) {
	RequireQuint(f)
	f.Add([]byte{255, 'q', 'c', 48})
	f.Add([]byte{255, 'q', 'c', byte(qenv.BytesVersion)})
	encoded, err := qenv.EncodeChoices([]qenv.Choice{{Kind: "sched.input", N: 4, Value: 2}}, qenv.NoFaults)
	if err != nil {
		f.Fatal(err)
	}
	System{Binding: "../validate/testdata/account.yaml", Rates: qenv.NoFaults, Run: func(c qenv.Chooser) error {
		amount := c.Choose("sched.input", 4) + 1
		s := qenv.New(c)
		defer s.Close()
		s.Spawn("client", func(ctx context.Context) {
			qobs.Record(ctx, "deposit", nil, "amount", amount, "obs.balance", amount)
		})
		return s.Run(time.Second)
	}}.Fuzz(f, encoded)
}
